    <option>Asymptotes only</option>
    <option selected>Combined</option>
  </select>
</label>
<span id="readout" style="font-size:11px;font-family:ui-monospace,Consolas,monospace;line-height:1.55;white-space:pre-wrap;color:#222;border-top:1px solid #e0e0e0;padding-top:6px"></span>
<span style="font-size:10px;color:#666;line-height:1.4">Hover or click the curve and the dashed guides for details.</span>
<!-- @FIGURE_UI_END -->
// @FIGURE_CODE_BEGIN
(function () {
  var NAVY = '#1F4E79', TEAL = '#1B7B7B', ORANGE = '#E8722C', AXC = '#111';

  function f(x) { return 3 * x + 1 + 2 / (x - 1); }
  function slant(x) { return 3 * x + 1; }

  // ---- curve sampling (two branches, never connected across the pole) ----
  function genBranch(a, b, step, lim) {
    var pts = [];
    for (var x = a; x <= b + 1e-9; x += step) {
      var y = f(x);
      if (isFinite(y) && y > -lim && y < lim) pts.push({ x: x, y: y });
    }
    return pts;
  }
  var leftPts = genBranch(-5, 0.999, 0.004, 40);
  var rightPts = genBranch(1.001, 5, 0.004, 40);

  var canvas = document.createElement('canvas');
  canvas.style.cssText = 'width:100%;height:100%;display:block';
  document.getElementById('container').appendChild(canvas);

  var probeX = 2.5;
  var mode = 'Combined';

  function snap(v) {
    if (Math.abs(v - 1) < 0.1) return v < 1 ? 0.9 : 1.1;
    return v;
  }

  // ---------------- custom drawing plugin ----------------
  function halo(ctx, text, x, y, color, align, baseline, font, w) {
    ctx.font = font; ctx.textAlign = align; ctx.textBaseline = baseline;
    ctx.lineJoin = 'round'; ctx.strokeStyle = '#fff'; ctx.lineWidth = w;
    ctx.strokeText(text, x, y);
    ctx.fillStyle = color; ctx.fillText(text, x, y);
  }
  function tri(ctx, x, y, dx, dy, s, color) {
    ctx.beginPath();
    var px = -dy, py = dx;
    ctx.moveTo(x + dx * s, y + dy * s);
    ctx.lineTo(x - dx * s * 0.2 + px * s * 0.55, y - dy * s * 0.2 + py * s * 0.55);
    ctx.lineTo(x - dx * s * 0.2 - px * s * 0.55, y - dy * s * 0.2 - py * s * 0.55);
    ctx.closePath(); ctx.fillStyle = color; ctx.fill();
  }

  var figPlugin = {
    id: 'figdeco',
    afterDatasetsDraw: function (chart) {
      var ca = chart.chartArea; if (!ca) return;
      var ctx = chart.ctx, sx = chart.scales.x, sy = chart.scales.y;
      var u = Math.min(ca.right - ca.left, ca.bottom - ca.top) / 460;
      var fs = Math.max(8, Math.min(17, 13 * u));
      var fsm = Math.max(7, Math.min(14, 11 * u));
      var hw = Math.max(2, 3 * u);
      var ar = Math.max(4, 7.5 * u);

      var y0 = sy.getPixelForValue(0), x0 = sx.getPixelForValue(0);

      ctx.save();
      // ---- axis arrowheads + letters ----
      tri(ctx, ca.right, y0, 1, 0, ar, AXC);
      tri(ctx, ca.left, y0, -1, 0, ar, AXC);
      tri(ctx, x0, ca.top, 0, -1, ar, AXC);
      tri(ctx, x0, ca.bottom, 0, 1, ar, AXC);
      halo(ctx, 'x', ca.right + 7 * u, y0, AXC, 'left', 'middle', 'italic bold ' + fs + 'px Arial', hw);
      halo(ctx, 'y', x0 + 4 * u, ca.top - 8 * u, AXC, 'left', 'bottom', 'italic bold ' + fs + 'px Arial', hw);

      var showCurve = (mode !== 'Asymptotes only');
      var showAsym = (mode !== 'Curve only');

      // ---- asymptote labels ----
      if (showAsym) {
        halo(ctx, 'Slant asymptote', sx.getPixelForValue(1.95), sy.getPixelForValue(6.0),
          TEAL, 'left', 'middle', 'bold ' + fs + 'px Arial', hw);
        halo(ctx, 'y = 3x + 1', sx.getPixelForValue(1.95), sy.getPixelForValue(4.6),
          TEAL, 'left', 'middle', 'bold italic ' + fs + 'px Arial', hw);
        halo(ctx, 'x = 1', sx.getPixelForValue(1.14), sy.getPixelForValue(-8.7),
          ORANGE, 'left', 'middle', 'bold italic ' + fs + 'px Arial', hw);
      }

      // ---- probe ----
      if (showCurve) {
        var xs = snap(probeX), ys = f(xs), yl = slant(xs);
        var px = sx.getPixelForValue(xs);
        var pyTrue = sy.getPixelForValue(ys);
        var py = Math.max(ca.top + 3, Math.min(ca.bottom - 3, pyTrue));
        var offFrame = Math.abs(pyTrue - py) > 0.5;
        var pyS = Math.max(ca.top + 2, Math.min(ca.bottom - 2, sy.getPixelForValue(yl)));
        var pxA = sx.getPixelForValue(1);

        if (showAsym) {
          ctx.save();
          ctx.beginPath(); ctx.rect(ca.left, ca.top, ca.right - ca.left, ca.bottom - ca.top); ctx.clip();
          ctx.setLineDash([Math.max(2, 4 * u), Math.max(2, 3 * u)]);
          ctx.lineWidth = Math.max(0.8, 1.3 * u);
          // vertical gap to slant line
          ctx.strokeStyle = TEAL;
          ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(px, pyS); ctx.stroke();
          // horizontal distance to x = 1
          ctx.strokeStyle = ORANGE;
          ctx.beginPath(); ctx.moveTo(px, py); ctx.lineTo(pxA, py); ctx.stroke();
          ctx.restore();

          var gap = Math.abs(2 / (xs - 1));
          var dx1 = Math.abs(xs - 1);
          var midY = (py + pyS) / 2;
          var side = (xs > 1) ? 1 : -1;
          halo(ctx, 'gap = ' + gap.toFixed(2), px + side * 7 * u, midY, TEAL,
            side > 0 ? 'left' : 'right', 'middle', 'bold ' + fsm + 'px Arial', hw);
          var midX = (px + pxA) / 2;
          halo(ctx, '|x \u2212 1| = ' + dx1.toFixed(2), midX, py - 7 * u, ORANGE,
            'center', 'bottom', 'bold ' + fsm + 'px Arial', hw);
        }

        // marker
        var r = Math.max(3, 5 * u);
        if (offFrame) {
          tri(ctx, px, py, 0, (pyTrue < py ? -1 : 1), r * 1.6, NAVY);
        } else {
          ctx.beginPath(); ctx.arc(px, py, r, 0, Math.PI * 2);
          ctx.fillStyle = NAVY; ctx.fill();
          ctx.lineWidth = Math.max(1, 1.6 * u); ctx.strokeStyle = '#fff'; ctx.stroke();
        }
      }
      ctx.restore();
    }
  };

  // ---------------- chart ----------------
  var chart = new Chart(canvas.getContext('2d'), {
    type: 'line',
    data: {
      datasets: [
        { label: 'left', data: leftPts, borderColor: NAVY, borderWidth: 2.7, pointRadius: 0, tension: 0, normalized: true, fill: false },
        { label: 'right', data: rightPts, borderColor: NAVY, borderWidth: 2.7, pointRadius: 0, tension: 0, normalized: true, fill: false },
        {
          label: 'slant', data: [{ x: -5, y: -14 }, { x: 5, y: 16 }], borderColor: TEAL, borderWidth: 1.8,
          borderDash: [6, 5], pointRadius: 0, tension: 0, fill: false
        },
        {
          label: 'vert', data: [{ x: 1, y: -12.6 }, { x: 1, y: 12.6 }], borderColor: ORANGE, borderWidth: 1.8,
          borderDash: [6, 5], pointRadius: 0, tension: 0, fill: false
        }
      ]
    },
    options: {
      responsive: true,
      maintainAspectRatio: false,
      animation: false,
      layout: { padding: { top: 26, right: 26, bottom: 8, left: 6 } },
      plugins: { legend: { display: false }, tooltip: { enabled: false } },
      scales: {
        x: {
          type: 'linear', min: -5, max: 5, position: { y: 0 },
          ticks: {
            stepSize: 1, autoSkip: false, maxRotation: 0, color: '#000', padding: 4,
            font: { size: 12 }, callback: function (v) { return v === 0 ? '' : v; }
          },
          grid: { display: true, drawOnChartArea: false, drawTicks: true, tickLength: 6, tickColor: '#000', tickWidth: 1.2, color: 'transparent' },
          border: { display: true, color: AXC, width: 1.6 }
        },
        y: {
          type: 'linear', min: -12, max: 12, position: { x: 0 },
          ticks: {
            stepSize: 2, autoSkip: false, color: '#000', padding: 5,
            font: { size: 12 }, callback: function (v) { return v === 0 ? '' : v; }
          },
          grid: { display: true, drawOnChartArea: false, drawTicks: true, tickLength: 6, tickColor: '#000', tickWidth: 1.2, color: 'transparent' },
          border: { display: true, color: AXC, width: 1.6 }
        }
      },
      onResize: function (c, size) { applyScale(c, size.width, size.height); }
    },
    plugins: [figPlugin]
  });
  window.__markRendered();

  function applyScale(c, w, h) {
    var u = Math.min(w, h) / 500;
    var bw = Math.max(1.2, 2.8 * u);
    c.data.datasets[0].borderWidth = bw;
    c.data.datasets[1].borderWidth = bw;
    var dw = Math.max(0.9, 1.9 * u);
    c.data.datasets[2].borderWidth = dw;
    c.data.datasets[3].borderWidth = dw;
    var dash = [Math.max(3, 6 * u), Math.max(2.5, 5 * u)];
    c.data.datasets[2].borderDash = dash;
    c.data.datasets[3].borderDash = dash;
    var fz = Math.max(7, Math.min(15, 12 * u));
    c.options.scales.x.ticks.font = { size: fz };
    c.options.scales.y.ticks.font = { size: fz };
    c.options.scales.x.grid.tickLength = Math.max(3, 6 * u);
    c.options.scales.y.grid.tickLength = Math.max(3, 6 * u);
  }
  applyScale(chart, chart.width, chart.height);
  chart.update('none');

  // ---------------- controls ----------------
  function fmt(v) { return (Math.abs(v) >= 1000 ? v.toExponential(2) : v.toFixed(2)); }

  function updateReadout() {
    var xs = snap(probeX), lin = slant(xs), rem = 2 / (xs - 1), val = lin + rem;
    var txt =
      'f(x) = (3x\u00B2 \u2212 2x + 1)/(x \u2212 1)\n' +
      '     = 3x + 1 + 2/(x \u2212 1)\n\n' +
      'x        = ' + xs.toFixed(2) + '\n' +
      '3x + 1   = ' + fmt(lin) + '   \u2190 slant part\n' +
      '2/(x\u22121)  = ' + fmt(rem) + '   \u2190 remainder\n' +
      'f(x)     = ' + fmt(val) + '\n' +
      '|x \u2212 1|  = ' + Math.abs(xs - 1).toFixed(2);
    document.getElementById('readout').textContent = txt;
  }

  window.update_xProbe = function (v) {
    probeX = v;
    updateReadout();
    chart.update('none');
  };

  window.update_viewMode = function (v) {
    mode = v;
    var showCurve = (v !== 'Asymptotes only');
    var showAsym = (v !== 'Curve only');
    chart.data.datasets[0].hidden = !showCurve;
    chart.data.datasets[1].hidden = !showCurve;
    chart.data.datasets[2].hidden = !showAsym;
    chart.data.datasets[3].hidden = !showAsym;
    chart.update('none');
  };

  // ---------------- demo steps ----------------
  var steps = [
    {
      title: 'The whole picture',
      narration: 'f(x) = (3x\u00B2 \u2212 2x + 1)/(x \u2212 1) in dark blue, with its vertical asymptote x = 1 (orange) and slant asymptote y = 3x + 1 (teal). Use \u25B6 to walk through why both lines are there.',
      state: { viewMode: 'Combined', xProbe: 2.5 }
    },
    {
      title: 'The curve by itself',
      narration: 'Only the solid blue graph is shown, in two separate branches. Both branches seem steered by something invisible: they run off vertically near x = 1 and straighten into a steep line at both far ends.',
      state: { viewMode: 'Curve only', xProbe: 2.5 }
    },
    {
      title: 'The two boundary lines',
      narration: 'Now only the guides: the orange dashed line x = 1, where the denominator is zero, and the teal dashed line y = 3x + 1, the quotient of the long division. Neither is part of the function \u2014 they are the boundaries it negotiates.',
      state: { viewMode: 'Asymptotes only', xProbe: 2.5 }
    },
    {
      title: 'Far out: the slant asymptote wins',
      narration: 'With everything drawn, the probe sits at x = 4. The vertical gap between curve and teal line is tiny, because the remainder 2/(x \u2212 1) is nearly zero \u2014 the end behavior is linear, not horizontal.',
      state: { viewMode: 'Combined', xProbe: 4 }
    },
    {
      title: 'Close in: the vertical asymptote wins',
      narration: 'At x = 1.1 the horizontal distance to x = 1 is small, so 2/(x \u2212 1) is huge and the point rockets off the top of the frame, far from the slant line. Local blow-up is controlled entirely by the vertical asymptote.',
      state: { viewMode: 'Combined', xProbe: 1.1 }
    },
    {
      title: 'Cross to the left branch',
      narration: 'At x = \u22123 the mirror behavior appears: the curve again presses against the teal line, while approaching x = 1 from the left sends it downward off the frame. Same two boundaries, opposite signs.',
      state: { viewMode: 'Combined', xProbe: -3 }
    }
  ];
  var cur = 0;

  function applyStep(i) {
    cur = (i + steps.length) % steps.length;
    var st = steps[cur];
    var vi = document.getElementById('viewModeInput');
    vi.value = st.state.viewMode;
    window.update_viewMode(st.state.viewMode);
    var xi = document.getElementById('xProbeInput');
    xi.value = st.state.xProbe;
    document.getElementById('xProbeVal').value = st.state.xProbe;
    window.update_xProbe(+st.state.xProbe);
    document.getElementById('demoNarration').innerHTML =
      '<b>' + st.title + '</b><br>' + st.narration;
    document.getElementById('stepLabel').textContent = 'Step ' + (cur + 1) + ' / ' + steps.length;
  }
  window.nextStep = function () { applyStep(cur + 1); };
  window.prevStep = function () { applyStep(cur - 1); };

  // ---------------- hover / click ----------------
  function hit(e) {
    var rect = canvas.getBoundingClientRect();
    var px = (e.clientX - rect.left), py = (e.clientY - rect.top);
    var ca = chart.chartArea;
    if (!ca || px < ca.left || px > ca.right || py < ca.top || py > ca.bottom) return null;
    var sx = chart.scales.x, sy = chart.scales.y;
    var x = sx.getValueForPixel(px);
    var showCurve = (mode !== 'Asymptotes only'), showAsym = (mode !== 'Curve only');
    var tol = 9;

    if (showCurve) {
      var xs = snap(probeX);
      var ppx = sx.getPixelForValue(xs);
      var ppy = Math.max(ca.top + 3, Math.min(ca.bottom - 3, sy.getPixelForValue(f(xs))));
      if (Math.hypot(px - ppx, py - ppy) < 12) {
        return {
          k: 'probe',
          t: 'Probe at x = ' + xs.toFixed(2) + ':  f(x) = ' + fmt(f(xs)) +
            ' = ' + fmt(slant(xs)) + ' + ' + fmt(2 / (xs - 1)),
          title: 'The probe point',
          body: 'This dot sits on the curve. Its height is always the slant value 3x + 1 plus the remainder 2/(x \u2212 1). The teal connector measures that remainder; the orange connector measures how far x is from the pole at 1.'
        };
      }
    }
    if (showAsym && Math.abs(px - sx.getPixelForValue(1)) < tol) {
      return {
        k: 'vert', t: 'Vertical asymptote x = 1',
        title: 'Vertical asymptote x = 1',
        body: 'The denominator x \u2212 1 is zero at x = 1 while the numerator is not, so the remainder term 2/(x \u2212 1) grows without bound there. The curve is torn upward on the right of the line and downward on its left.'
      };
    }
    if (showCurve && Math.abs(x - 1) > 0.02) {
      var cy = sy.getPixelForValue(f(x));
      if (Math.abs(py - cy) < tol + 3) {
        return {
          k: 'curve', t: 'f(x) = (3x\u00B2 \u2212 2x + 1)/(x \u2212 1) = 3x + 1 + 2/(x \u2212 1)',
          title: 'The rational function',
          body: 'Long division of 3x\u00B2 \u2212 2x + 1 by x \u2212 1 gives quotient 3x + 1 with remainder 2. So f(x) = 3x + 1 + 2/(x \u2212 1): a line plus a term that vanishes at infinity and explodes at x = 1.'
        };
      }
    }
    if (showAsym) {
      var ly = sy.getPixelForValue(slant(x));
      if (Math.abs(py - ly) < tol) {
        return {
          k: 'slant', t: 'Slant asymptote y = 3x + 1',
          title: 'Slant asymptote y = 3x + 1',
          body: 'Because the numerator degree is exactly one more than the denominator degree, the quotient of the long division is linear. As |x| grows, 2/(x \u2212 1) \u2192 0, so the graph settles onto this line from above on the right and from below on the left.'
        };
      }
    }
    return null;
  }

  canvas.addEventListener('mousemove', function (e) {
    var h = hit(e);
    if (h) { canvas.style.cursor = 'pointer'; showTooltip(h.t, e); }
    else { canvas.style.cursor = 'default'; hideTooltip(); }
  });
  canvas.addEventListener('mouseleave', function () { hideTooltip(); });
  canvas.addEventListener('click', function (e) {
    var h = hit(e);
    if (h) showPopup(h.title, h.body);
  });

  applyStep(0);
})();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using Chart.js.

CONCEPT: When a rational function's numerator degree is exactly one more than its denominator's, long division splits it into a linear part plus a vanishing remainder, so the graph blows up at the vertical asymptote x = 1 while its ends settle onto the slant asymptote y = 3x + 1.
KEY INSIGHT (what students should walk away understanding): Writing f(x) as 3x + 1 + 2/(x - 1) explains the whole picture at once: the linear piece is the slant asymptote the ends ride on, and the fractional piece is the term that blows up at x = 1 and dies off at infinity.
DEMO STEPS: 5 guided steps — implement the step player in #ui

FULL BLUEPRINT:
